-- Survey masters, workflow, customer confirmation, packing plan inputs, and starter data for SQL Server.
SET XACT_ABORT ON; BEGIN TRANSACTION;

CREATE TABLE [dbo].[HouseholdItems] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[Code] NVARCHAR(40) NOT NULL,[Name] NVARCHAR(160) NOT NULL,[VolumeCbm] DECIMAL(12,3) NOT NULL,[Description] NVARCHAR(500) NULL,[IsActive] BIT NOT NULL,CONSTRAINT [UX_HouseholdItems_Tenant_Code] UNIQUE([TenantId],[Code]));
CREATE INDEX [IX_HouseholdItems_Tenant] ON [dbo].[HouseholdItems]([TenantId]);
CREATE TABLE [dbo].[PackingMaterials] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[Code] NVARCHAR(40) NOT NULL,[Name] NVARCHAR(160) NOT NULL,[Unit] NVARCHAR(40) NOT NULL,[CurrentUnitCost] DECIMAL(18,2) NOT NULL,[Description] NVARCHAR(500) NULL,[IsActive] BIT NOT NULL,CONSTRAINT [UX_PackingMaterials_Tenant_Code] UNIQUE([TenantId],[Code]));
CREATE INDEX [IX_PackingMaterials_Tenant] ON [dbo].[PackingMaterials]([TenantId]);
CREATE TABLE [dbo].[BoxTypes] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[Code] NVARCHAR(40) NOT NULL,[Name] NVARCHAR(160) NOT NULL,[CapacityCbm] DECIMAL(12,3) NOT NULL,[Description] NVARCHAR(500) NULL,[IsActive] BIT NOT NULL,CONSTRAINT [UX_BoxTypes_Tenant_Code] UNIQUE([TenantId],[Code]));
CREATE INDEX [IX_BoxTypes_Tenant] ON [dbo].[BoxTypes]([TenantId]);
CREATE TABLE [dbo].[BoxTypeMaterials] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[BoxTypeId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[BoxTypes]([Id]) ON DELETE CASCADE,[MaterialId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[PackingMaterials]([Id]),[Quantity] DECIMAL(12,3) NOT NULL,CONSTRAINT [UX_BoxTypeMaterials_Box_Material] UNIQUE([BoxTypeId],[MaterialId]));
CREATE INDEX [IX_BoxTypeMaterials_Tenant] ON [dbo].[BoxTypeMaterials]([TenantId]);
CREATE TABLE [dbo].[Surveys] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[SurveyNumber] NVARCHAR(40) NOT NULL,[SalesLeadId] UNIQUEIDENTIFIER NULL REFERENCES [dbo].[SalesLeads]([Id]),[CustomerName] NVARCHAR(160) NOT NULL,[Phone] NVARCHAR(40) NOT NULL,[Email] NVARCHAR(254) NULL,[AssignedEmployeeId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Employees]([Id]),[ScheduledAtUtc] DATETIMEOFFSET NOT NULL,[Address] NVARCHAR(600) NOT NULL,[Latitude] DECIMAL(10,7) NULL,[Longitude] DECIMAL(10,7) NULL,[Status] NVARCHAR(30) NOT NULL,[Notes] NVARCHAR(2000) NULL,[StartedAtUtc] DATETIMEOFFSET NULL,[EndedAtUtc] DATETIMEOFFSET NULL,[ScheduleConfirmedAtUtc] DATETIMEOFFSET NULL,[ItemsConfirmedAtUtc] DATETIMEOFFSET NULL,[CustomerNotes] NVARCHAR(2000) NULL,[ConfirmationTokenHash] NVARCHAR(64) NULL,[ConfirmationExpiresAtUtc] DATETIMEOFFSET NULL,[CreatedAtUtc] DATETIMEOFFSET NOT NULL,[UpdatedAtUtc] DATETIMEOFFSET NOT NULL,CONSTRAINT [UX_Surveys_Tenant_Number] UNIQUE([TenantId],[SurveyNumber]));
CREATE UNIQUE INDEX [UX_Surveys_ConfirmationToken] ON [dbo].[Surveys]([ConfirmationTokenHash]) WHERE [ConfirmationTokenHash] IS NOT NULL; CREATE INDEX [IX_Surveys_Tenant_Latest] ON [dbo].[Surveys]([TenantId],[SerialNo] DESC); CREATE INDEX [IX_Surveys_Assignee_Date] ON [dbo].[Surveys]([AssignedEmployeeId],[ScheduledAtUtc]);
CREATE TABLE [dbo].[SurveyRooms] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[SurveyId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Surveys]([Id]) ON DELETE CASCADE,[Name] NVARCHAR(120) NOT NULL,[DisplayOrder] INT NOT NULL);
CREATE INDEX [IX_SurveyRooms_Tenant] ON [dbo].[SurveyRooms]([TenantId]); CREATE INDEX [IX_SurveyRooms_Survey] ON [dbo].[SurveyRooms]([SurveyId]);
CREATE TABLE [dbo].[SurveyItems] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[SurveyId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Surveys]([Id]) ON DELETE CASCADE,[RoomId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[SurveyRooms]([Id]),[HouseholdItemId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[HouseholdItems]([Id]),[Quantity] INT NOT NULL,[VolumePerUnitCbm] DECIMAL(12,3) NOT NULL,[Notes] NVARCHAR(500) NULL);
CREATE INDEX [IX_SurveyItems_Tenant] ON [dbo].[SurveyItems]([TenantId]); CREATE INDEX [IX_SurveyItems_Survey] ON [dbo].[SurveyItems]([SurveyId]);
CREATE TABLE [dbo].[SurveyExtraMaterials] ([SerialNo] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[SurveyId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Surveys]([Id]) ON DELETE CASCADE,[MaterialId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[PackingMaterials]([Id]),[Quantity] DECIMAL(12,3) NOT NULL,CONSTRAINT [UX_SurveyExtraMaterials_Survey_Material] UNIQUE([SurveyId],[MaterialId]));
CREATE INDEX [IX_SurveyExtraMaterials_Tenant] ON [dbo].[SurveyExtraMaterials]([TenantId]);

INSERT INTO [dbo].[HouseholdItems]([Id],[TenantId],[Code],[Name],[VolumeCbm],[Description],[IsActive])
SELECT NEWID(),t.[Id],d.Code,d.Name,d.Volume,d.Description,1 FROM [dbo].[Tenants] t CROSS JOIN (VALUES
('KING_BED','King bed',5.000,'King bed including frame'),('QUEEN_BED','Queen bed',4.000,'Queen bed including frame'),('CHAIR','Dining chair',1.000,'Standard chair'),('BIG_SOFA','Large sofa',3.000,'Three or four-seat sofa'),('DINING_TABLE','Dining table',2.500,'Six-seat dining table'),('WARDROBE','Wardrobe',4.500,'Large wardrobe'),('TV_55','Television 55 inch',0.500,'Flat-screen television'),('FRIDGE','Refrigerator',1.500,'Double-door refrigerator')) d(Code,Name,Volume,Description)
WHERE NOT EXISTS(SELECT 1 FROM [dbo].[HouseholdItems] x WHERE x.[TenantId]=t.[Id] AND x.[Code]=d.Code);
INSERT INTO [dbo].[PackingMaterials]([Id],[TenantId],[Code],[Name],[Unit],[CurrentUnitCost],[Description],[IsActive])
SELECT NEWID(),t.[Id],d.Code,d.Name,d.Unit,d.Cost,d.Description,1 FROM [dbo].[Tenants] t CROSS JOIN (VALUES
('CARDBOARD','Corrugated cardboard','sheet',120.00,'Box wall material'),('TAPE','Packing tape','roll',75.00,'Heavy-duty tape'),('BUBBLE_WRAP','Bubble wrap','meter',35.00,'Fragile-item wrapping'),('FOAM','Protective foam','sheet',55.00,'Impact protection'),('STRETCH_WRAP','Stretch wrap','roll',280.00,'Furniture and surface protection')) d(Code,Name,Unit,Cost,Description)
WHERE NOT EXISTS(SELECT 1 FROM [dbo].[PackingMaterials] x WHERE x.[TenantId]=t.[Id] AND x.[Code]=d.Code);
INSERT INTO [dbo].[BoxTypes]([Id],[TenantId],[Code],[Name],[CapacityCbm],[Description],[IsActive])
SELECT NEWID(),t.[Id],d.Code,d.Name,d.Capacity,d.Description,1 FROM [dbo].[Tenants] t CROSS JOIN (VALUES
('SMALL','Small box',1.000,'Small household carton'),('MEDIUM','Medium box',3.000,'General household carton'),('LARGE','Large box',5.000,'Large-item carton'),('XL','Extra-large crate',8.000,'Reinforced crate for bulky items')) d(Code,Name,Capacity,Description)
WHERE NOT EXISTS(SELECT 1 FROM [dbo].[BoxTypes] x WHERE x.[TenantId]=t.[Id] AND x.[Code]=d.Code);
INSERT INTO [dbo].[BoxTypeMaterials]([Id],[TenantId],[BoxTypeId],[MaterialId],[Quantity])
SELECT NEWID(),b.[TenantId],b.[Id],m.[Id],r.Quantity FROM [dbo].[BoxTypes] b JOIN (VALUES ('SMALL','CARDBOARD',2.0),('SMALL','TAPE',0.15),('MEDIUM','CARDBOARD',3.0),('MEDIUM','TAPE',0.25),('LARGE','CARDBOARD',5.0),('LARGE','TAPE',0.40),('LARGE','FOAM',1.0),('XL','CARDBOARD',8.0),('XL','TAPE',0.75),('XL','FOAM',2.0)) r(BoxCode,MaterialCode,Quantity) ON r.BoxCode=b.[Code] JOIN [dbo].[PackingMaterials] m ON m.[TenantId]=b.[TenantId] AND m.[Code]=r.MaterialCode
WHERE NOT EXISTS(SELECT 1 FROM [dbo].[BoxTypeMaterials] x WHERE x.[BoxTypeId]=b.[Id] AND x.[MaterialId]=m.[Id]);

COMMIT TRANSACTION;
